import hashlib
import json
from pathlib import Path

ROOT = Path('/app/applet')
EXISTING_PV = json.loads((ROOT / 'English/englishPhrasalVerbs.json').read_text(encoding='utf8'))
EXISTING_VOCAB = json.loads((ROOT / 'English/englishVocabulary.json').read_text(encoding='utf8'))
EXISTING_COL = json.loads((ROOT / 'English/englishCollocations.json').read_text(encoding='utf8'))
EXISTING_REG = json.loads((ROOT / 'English/englishRegional.json').read_text(encoding='utf8'))

taken_terms = set()
for d in EXISTING_PV:
    for c in d['cards']:
        taken_terms.add(c['term'].lower())
for d in EXISTING_VOCAB:
    for c in d['cards']:
        taken_terms.add(c['term'].lower())
for d in EXISTING_COL:
    for c in d['cards']:
        taken_terms.add(c['term'].lower())
for d in EXISTING_REG:
    for c in d['cards']:
        taken_terms.add(c['american']['term'].lower())
        taken_terms.add(c['british']['term'].lower())

