for deck in EXISTING_PV:
    for card in deck['cards']:
        if card['term'] in EXISTING_ENRICH:
            ph, syn, ant = EXISTING_ENRICH[card['term']]
            card['phonetic'] = ph
            if syn:
                card['synonyms'] = syn
            if ant:
                card['antonyms'] = ant

