existing_ids = {c['id'] for d in EXISTING_PV for c in d['cards']}
added_count = 0

for deck_spec in NEW_DECKS:
    cards = []
    for item in deck_spec['cards']:
        term, phonetic, meaning, syn, ant, ex1, tr1, ex2, tr2, notes = item
        key = term.lower()
        if key in taken_terms:
            # Avoid exact duplicate with existing 4041 terms unless it was only an existing phrasal (none should duplicate)
            continue
        taken_terms.add(key)
        slug = "-".join(key.replace("'", "").split())
        digest = hashlib.sha1(key.encode()).hexdigest()[:10]
        cid = f"en-phrasal-{slug}-{digest}"
        while cid in existing_ids:
            digest = hashlib.sha1((cid + "x").encode()).hexdigest()[:10]
            cid = f"en-phrasal-{slug}-{digest}"
        existing_ids.add(cid)
        card = {
            "id": cid,
            "term": term,
            "phonetic": phonetic,
            "meaning": meaning,
            "synonyms": syn,
            "antonyms": ant,
            "examples": [
                {"sentence": ex1, "translation": tr1},
                {"sentence": ex2, "translation": tr2},
            ],
            "notes": notes,
        }
        cards.append(card)
        added_count += 1
    if cards:
        EXISTING_PV.append({
            "id": deck_spec['id'],
            "title": deck_spec['title'],
            "topic": deck_spec['topic'],
            "cards": cards,
        })

(ROOT / 'English/englishPhrasalVerbs.json').write_text(
    json.dumps(EXISTING_PV, ensure_ascii=False, indent=2) + "\n", encoding='utf8'
)
print(f"Phrasal verbs updated: {len(EXISTING_PV)} decks, added {added_count}, total {sum(len(d['cards']) for d in EXISTING_PV)}")
